window.initMilaknightFunctions = function (e) {
  "use strict";

  // Project nav
  const navLinks = document.querySelectorAll(".our-Project-nav a"),
    items = Array.from(document.querySelectorAll(".col-lg-4, .col-md-6"));
  function filterItems(filterVal) {
    const f = (filterVal)
      ? "*" === filterVal.trim()
        ? "*"
        : filterVal.startsWith(".")
          ? filterVal.slice(1)
          : filterVal
      : "*";
    items.forEach((item) => {
      item.querySelector(".post-item") &&
        ("*" === f || item.classList.contains(f)
          ? item.classList.remove("post-hidden")
          : item.classList.add("post-hidden"));
    });
  }
  navLinks.forEach((t) => {
    t.setAttribute("role", "button");
    t.addEventListener("click", function (evt) {
      evt.preventDefault();
      const a = this.getAttribute("data-filter") || "*";
      navLinks.forEach((l) => l.classList.remove("active-btn"));
      this.classList.add("active-btn");
      filterItems(a);
    });
    t.addEventListener("keydown", function (evt) {
      ("Enter" !== evt.key && " " !== evt.key) ||
        (evt.preventDefault(), this.click());
    });
  });
  const activeNav = document.querySelector(".our-Project-nav a.active-btn");
  filterItems(activeNav ? activeNav.getAttribute("data-filter") : "*");

  e(window).off("scroll.milaknight").on("scroll.milaknight", function () {
    e(this).scrollTop() > 0
      ? e("header").addClass("active")
      : e("header").removeClass("active");
  });
  
  var t = e(window);

  e(".preloader").fadeOut(600);

  if (e(".active-sticky-header").length) {
    function o() {
      e("header.main-header").css(
        "height",
        e("header .header-sticky").outerHeight(),
      );
    }
    t.off("resize.milaknight").on("resize.milaknight", function () {
      o();
    });
    e(window).off("scroll.milaknight-sticky").on("scroll.milaknight-sticky", function () {
      var topScroll = e(window).scrollTop();
      o();
      var i = e("header .header-sticky").outerHeight();
      (e("header .header-sticky").toggleClass("hide", topScroll > i + 100),
        e("header .header-sticky").toggleClass("active", topScroll > 600));
    });
  }

  if (e("a[href='#top']").length) {
    e("a[href='#top']")
      .off("click")
      .click(function () {
        return (e("html, body").animate({ scrollTop: 0 }, "slow"), !1);
      });
  }

  if (
    e(".counter").length &&
    !e(".counter").hasClass("counter-initialized")
  ) {
    e(".counter")
      .addClass("counter-initialized")
      .counterUp({ delay: 6, time: 1e3 });
  }

  if (typeof gsap !== 'undefined' && e(".reveal").length) {
    gsap.registerPlugin(ScrollTrigger);
    document.querySelectorAll(".reveal").forEach((el) => {
      if (el.classList.contains("reveal-initialized")) return;
      el.classList.add("reveal-initialized");
      let tg = el.querySelector("img"),
        tls = gsap.timeline({
          scrollTrigger: { trigger: el, toggleActions: "play none none none" },
        });
      tls.set(el, { autoAlpha: 1 });
      tls.from(el, 1, { xPercent: 0, ease: Power2.out });
      if(tg) {
          tls.from(tg, 1, {
            xPercent: 100,
            scale: 1,
            delay: -1,
            ease: Power2.out,
          });
      }
    });
  }
  
  if (typeof SplitText !== 'undefined' && e(".text-anime-style-1").length) {
    let l = 0.05,
      n = 0.5;
    document.querySelectorAll(".text-anime-style-1").forEach((el) => {
      if (el.classList.contains("split-text-initialized")) return;
      el.classList.add("split-text-initialized");
      let ts = new SplitText(el, { type: "chars, words" });
      if(ts.words) {
          gsap.from(ts.words, {
            duration: 1,
            delay: n,
            x: 20,
            autoAlpha: 0,
            stagger: l,
            scrollTrigger: { trigger: el, start: "top 85%" },
          });
      }
    });
  }

  if (typeof SplitText !== 'undefined' && e(".text-anime-style-2").length) {
    let r = 0.03,
      s = 20,
      c = 0.1,
      d = "power2.out";
    document.querySelectorAll(".text-anime-style-2").forEach((el) => {
      if (el.classList.contains("split-text-initialized")) return;
      el.classList.add("split-text-initialized");
      let ts = new SplitText(el, { type: "chars, words" });
      if(ts.chars) {
          gsap.from(ts.chars, {
            duration: 1,
            delay: c,
            x: s,
            autoAlpha: 0,
            stagger: r,
            ease: d,
            scrollTrigger: { trigger: el, start: "top 85%" },
          });
      }
    });
  }

  if (typeof SplitText !== 'undefined' && e(".text-anime-style-3").length) {
    document.querySelectorAll(".text-anime-style-3").forEach((el) => {
      if (el.animation) { el.animation.progress(1).kill(); el.split.revert(); }
      el.split = new SplitText(el, {
        type: "lines,words,chars",
        linesClass: "split-line",
      });
      gsap.set(el, { perspective: 400 });
      if(el.split.chars) {
          gsap.set(el.split.chars, { opacity: 0, x: "50" });
          el.animation = gsap.to(el.split.chars, {
            scrollTrigger: { trigger: el, start: "top 90%" },
            x: "0",
            y: "0",
            rotateX: "0",
            opacity: 1,
            duration: 1,
            ease: Back.easeOut,
            stagger: 0.02,
          });
      }
    });
  }

  var px = e(".parallaxie");
  if (
    px.length &&
    t.width() > 991 &&
    !px.data("parallaxie-init") &&
    t.width() > 768
  ) {
    px.data("parallaxie-init", !0).parallaxie({ speed: 0.55, offset: 0 });
  }

  if (e(".gallery-items").length && !e(".gallery-items").data("magnific-init")) {
    e(".gallery-items")
      .data("magnific-init", !0)
      .magnificPopup({
        delegate: "a",
        type: "image",
        closeOnContentClick: !0,
        closeBtnInside: !1,
        mainClass: "mfp-with-zoom",
        image: { verticalFit: !0 },
        gallery: { enabled: !0 },
        zoom: {
          enabled: !0,
          duration: 300,
          opener: function (el) {
            return el.find("img");
          },
        },
      });
  }

  if (e(".project-item-boxes").length && !e(".project-item-boxes").data("isotope")) {
    var isotopeInstance = e(".project-item-boxes").isotope({
        itemSelector: ".project-item-box",
        layoutMode: "masonry",
        masonry: { columnWidth: 1 },
      });
    var navLi = e(".our-Project-nav li a");
    navLi.off("click").on("click", function (a) {
      var datFilter = e(this).attr("data-filter");
      isotopeInstance.isotope({ filter: datFilter });
      navLi.removeClass("active-btn");
      e(this).addClass("active-btn");
      a.preventDefault();
    });
    isotopeInstance.isotope({ filter: "*" });
  }

  if (e(".popup-video").length && !e(".popup-video").data("magnific-init")) {
    e(".popup-video")
      .data("magnific-init", !0)
      .magnificPopup({
        type: "iframe",
        mainClass: "mfp-fade",
        removalDelay: 160,
        preloader: !1,
        fixedContentPos: !0,
      });
  }

  if (e(".why-choose-content").length) {
    var whyItem = e(".why-choose-content").find(".why-choose-item");
    if (whyItem.length) {
      whyItem.off("mouseenter mouseleave").on({
        mouseenter: function () {
          if (!e(this).hasClass("active")) {
            whyItem.removeClass("active");
            e(this).addClass("active");
          }
        },
        mouseleave: function () {},
      });
    }
  }

};

// Auto run entirely if jQuery is already present
if (typeof jQuery !== 'undefined') {
  window.initMilaknightFunctions(jQuery);
}
